INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0346-a04-017-9', 'p0346', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從圍橋蕤於苦，斬蕤等四將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-046-0', 'p0347', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '繇遣樊能、于麋屯橫江津，張英屯當利口，以距術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-046-1', 'p0347', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '因渡江攻禮，禮突走，而樊能、于麋等復合衆襲奪牛渚屯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-049-2', 'p0347', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '繇遣樊能、張英屯江邊以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-050-3', 'p0347', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-050-4', 'p0347', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '堅薨，隨孫策討樊能、于麋等於橫江，擊張英於當利口，而船少，欲駐軍更求。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0347-a04-051-5', 'p0347', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '頃之，術復使賁與吳景共擊樊能、張英等，未能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a03-009-0', 'p0350', 'houhanshu', 'a03-009', '《後漢書·卷九》', '五年春正月，車騎將軍董承、偏將軍王服、越騎校尉种輯受密詔誅曹操，事洩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a03-072-1', 'p0350', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '承遂與劉備同謀，未發，會備出征，承更與偏將軍王服、長水校尉种輯、議郎吳碩結謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-001-2', 'p0350', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '傅子曰：漢末王公，多委王服，以幅巾為雅，是以袁紹、崔豹之徒，雖為將帥，皆著縑巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-002-3', 'p0350', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '夫然，故在三之義惇，臣子之恩篤，雍熈之化隆，經國之道固，聖人之所以通天地，厚人倫，顯至教，敦風俗，斯萬世不易之典，百王服膺之制也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0350-a04-057-4', 'p0350', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '若使易地而居，亦華戰王服耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-full-0', 'p0351', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '秋七月，射聲校尉馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-full-1', 'p0351', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-2', 'p0351', 'houhanshu', 'a03-008', '《後漢書·卷八》', '秋七月，射聲校尉馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-008-3', 'p0351', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-4', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '太尉趙謙罷，太常馬日磾為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-5', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月庚子，太尉馬日磾為太傅，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-009-6', 'p0351', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」太傅馬日磾薨于壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-054-7', 'p0351', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-064-8', 'p0351', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-064-9', 'p0351', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及李傕專政，使太傅馬日磾撫慰天下，以歧為副。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-070-10', 'p0351', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，太傅馬日磾奉使山東，及至淮南，數有意於袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a03-074-11', 'p0351', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '太傅日磾位為師保，任配東征，而耗亂王命，三輔決錄注曰：「馬日磾字翁叔，馬融之族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-006-12', 'p0351', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初平四年，天子使太傅馬日磾、太僕趙岐和解關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-006-13', 'p0351', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '李傕入長安，欲結術為援，以術為左將軍，封陽翟侯，假節，遣太傅馬日磾因循行拜授。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-007-14', 'p0351', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '其後尚喪與太傅馬日磾喪俱至京師，天子嘉尚忠烈，為之咨嗟，詔百官弔祭，拜子瑋郎中，而日磾不與焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-013-15', 'p0351', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '歆欲棄去，會天子使太傅馬日磾安集關東，日磾辟歆為掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-046-16', 'p0351', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '太傅馬日磾杖節安集關東，在壽春以禮辟策，表拜懷義校尉，術大將喬蕤、張勳皆傾心敬焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-056-17', 'p0351', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '時太傅馬日磾在壽春，辟治為掾，遷吳郡都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0351-a04-057-18', 'p0351', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '策旣定豫章，引軍還吳，饗賜將士，計功行賞，謂翻曰：「孤昔再至壽春，見馬日磾，及與中州士大夫會，語我東方人多才耳，但恨學問不博，語議之間，有所不及耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-035-0', 'p0352', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '及黨事起，乃與同郡孫嵩等四十餘人俱被禁錮，嵩字賔石，見趙岐傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-049-1', 'p0352', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」趙岐注云：「餓死者曰莩」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-049-2', 'p0352', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」趙岐注云：「貊，夷貊之人在荒者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-052-3', 'p0352', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」趙岐注云：「摟，牽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-058-4', 'p0352', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」趙岐注曰：「浩然，天氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-059-5', 'p0352', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」趙岐注云：「志士，守義者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-059-6', 'p0352', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '』」趙岐注云：「兼金，好金也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-070-7', 'p0352', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '趙岐注孟子曰：「倒縣猶困苦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-074-8', 'p0352', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '四年初，天子遣太僕趙岐和解關東，使各罷兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a03-074-9', 'p0352', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '太僕趙岐銜命來征，宣明陛下含弘之施，蠲除細故，與下更新，奉詔之日，引師南轅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-006-10', 'p0352', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '僕與太傅馬公、太僕趙岐、少府陰脩俱受詔命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-006-11', 'p0352', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初平四年，天子使太傅馬日磾、太僕趙岐和解關東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-010-12', 'p0352', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '象同郡趙岐作三輔決錄，恐時人不盡其意，故隱其書，唯以示象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0352-a04-018-13', 'p0352', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '至興平中，趙岐以太僕持節使安慰天下，南詣荊州，乃復與賔碩相遇，相對流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-009-0', 'p0353', 'houhanshu', 'a03-009', '《後漢書·卷九》', '封衞將軍董承為輔國將軍伏完等十三人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-010b-full-1', 'p0353', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '皇女華，延熹元年封陽安長公主，適不其侯輔國將軍伏完。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-2', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-3', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '於是封衞將軍董承、輔國將軍伏完等十餘人為列侯，贈沮儁為弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0353-a03-072-4', 'p0353', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '封衞將軍董承、輔國將軍伏完、侍中丁沖、种輯、尚書僕射鍾繇、尚書郭溥、御史中丞董芬、彭城相劉艾、馮翊韓斌、東郡太守楊衆、議郎羅邵、伏德、趙蕤為列侯，賞有功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-072-0', 'p0354', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓先遣將徐榮、李蒙四出虜掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-072-1', 'p0354', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a03-074-2', 'p0354', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」魏志曰：「操引兵西，將據成臯，到滎陽汴水，遇卓將徐榮，戰不利，士卒死傷多，操為流矢所中，所乘馬被創。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-001-3', 'p0354', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '到熒陽汴水，遇卓將徐榮，與戰不利，士卒死傷甚多。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-008-4', 'p0354', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '同郡徐榮為董卓中郎將，薦度為遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0354-a04-009-5', 'p0354', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖起義兵討董卓，至熒陽，為卓將徐榮所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-032-0', 'p0355', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-032-1', 'p0355', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後十餘日，陸議大破先主軍於猇亭，將軍馮習、張南等皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-055-2', 'p0355', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-058-3', 'p0355', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0355-a04-058-4', 'p0355', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '一爾勢成，通率諸軍同時俱攻，斬張南、馮習及胡王沙摩柯等首，破其四十餘營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a03-047-0', 'p0356', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '是時于窴王廣德新攻破莎車，遂雄張南道，于窴國去長安九千六百七十里，南與婼羌，西與姑墨接。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-001-1', 'p0356', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是月，袁熙大將焦觸、張南等叛攻熙、尚，熙、尚奔三郡烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-006-2', 'p0356', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '熈、尚為其將焦觸、張南所攻，奔遼西烏丸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-032-3', 'p0356', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '後十餘日，陸議大破先主軍於猇亭，將軍馮習、張南等皆沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-058-4', 'p0356', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a04-058-5', 'p0356', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '一爾勢成，通率諸軍同時俱攻，斬張南、馮習及胡王沙摩柯等首，破其四十餘營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0356-a05-011-6', 'p0356', 'jinshu', 'a05-011', '《晉書·卷十一》', '張南十四星曰天廟，天子之祖廟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0357-a04-045-0', 'p0357', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時又有義陽傅肜，先主退軍，斷後拒戰，兵人死盡，吳將語肜令降，肜罵曰：「吳狗！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0357-a04-058-1', 'p0357', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0360-a04-029-0', 'p0360', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」謂曹彪曰：「君據藩國，至五十七當厄於兵，宜善防之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0360-a04-029-1', 'p0360', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '曹彪封楚王，年五十七，坐與王淩通謀，賜死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0362-a05-019-0', 'p0362', 'jinshu', 'a05-019', '《晉書·卷十九》', '兼侍中散騎常侍荀奕、兼黃門侍郎散騎侍郎曹宇駁曰：「尚書三公曹奏讀秋令，儀注舊典未備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-003-0', 'p0365', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '中書監劉放、令孫資久專權寵，為朗等素所不善，懼有後害，陰圖間之，而宇常在帝側，故未得有言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-003-1', 'p0365', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略曰：帝旣從劉放計，召司馬宣王，自力為詔，旣封，顧呼宮中常所給使者曰：「辟邪來！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-2', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '正始元年春二月乙丑，加侍中中書監劉放、侍中中書令孫資為左右光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-3', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，以左光祿大夫劉放為驃騎將軍，右光祿大夫孫資為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-004-4', 'p0365', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九年春二月，衞將軍中書令孫資，癸巳，驃騎將軍中書監劉放，三月甲午，司徒衞臻，各遜位，以侯就第，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-009-5', 'p0365', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」於是帝使中書監劉放令孫資為詔曰：「昔吳漢佐光武，有征定四方之功，為大司馬，名稱于今。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-014-6', 'p0365', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放字子棄，涿郡人，漢廣陽順王子西鄉侯宏後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-014-7', 'p0365', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放文翰，孫資勤慎，並管喉舌，權聞當時，雅亮非體，是故譏諛之聲，每過其實矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-025-8', 'p0365', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '時中書監劉放、令孫資見信於主，制斷時政，大臣莫不交好，而毗不與往來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-028-9', 'p0365', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a04-028-10', 'p0365', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '中書令劉放、侍郎衞瓘、夏侯和等家皆怪問：『夫人一子在危難之中，何能無憂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-036-full-11', 'p0365', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄉人劉放亦奇其才，以女妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-036-12', 'p0365', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄉人劉放亦奇其才，以女妻焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0365-a05-039-13', 'p0365', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時議以勖傾國害時，孫資、劉放之匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-003-0', 'p0366', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及還，帝引見慰勞之，顧謂中書令孫資曰：「卿鄉里乃有爾曹快人，為將灼如此，朕復何憂乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-003-1', 'p0366', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '中書監劉放、令孫資久專權寵，為朗等素所不善，懼有後害，陰圖間之，而宇常在帝側，故未得有言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-2', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '正始元年春二月乙丑，加侍中中書監劉放、侍中中書令孫資為左右光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-3', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，以左光祿大夫劉放為驃騎將軍，右光祿大夫孫資為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-4', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '九年春二月，衞將軍中書令孫資，癸巳，驃騎將軍中書監劉放，三月甲午，司徒衞臻，各遜位，以侯就第，位特進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-5', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，以特進孫資為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-004-6', 'p0366', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚子，驃騎將軍孫資薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-009-7', 'p0366', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」於是帝使中書監劉放令孫資為詔曰：「昔吳漢佐光武，有征定四方之功，為大司馬，名稱于今。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-8', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '魏國旣建，與太原孫資俱為祕書郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-9', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '令孫資對曰：「上谷太守閻志，柔弟也，為比能素所歸信。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-014-10', 'p0366', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉放文翰，孫資勤慎，並管喉舌，權聞當時，雅亮非體，是故譏諛之聲，每過其實矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-015-11', 'p0366', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會諸葛亮出，緝上便宜，詔以問中書令孫資，資以為有籌略，遂召拜騎都尉，遣參征蜀軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-015-12', 'p0366', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '孫資別傳曰：資舉河東計吏，到許，薦於相府曰：「逵在絳邑，帥厲吏民，與賊郭援交戰，力盡而敗，為賊所俘，挺然直志，顏辭不屈；忠言聞於大衆，烈節顯于當時，雖古之直髮、據鼎，罔以加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-025-13', 'p0366', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '時中書監劉放、令孫資見信於主，制斷時政，大臣莫不交好，而毗不與往來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a04-028-14', 'p0366', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0366-a05-039-15', 'p0366', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '時議以勖傾國害時，孫資、劉放之匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a03-014-0', 'p0367', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '立十年薨，子哀王基嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a03-035-1', 'p0367', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '其門人山陽郗慮至御史大夫，東萊王基、清河崔琰著名於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-002-2', 'p0367', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '昔漢祖以秦中為國本，光武恃河內為王基，今朕復於此登壇受禪，天以此郡翼成大魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-004-3', 'p0367', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三年春正月，荊州刺史王基、新城太守州泰攻吳，破之，降者數千口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-011-4', 'p0367', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初，脩識高柔於弱冠，異王基於幼童，終皆遠至，世稱其知人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-011-5', 'p0367', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '正始二年，太僕陶丘一、永寧衞尉孟觀、侍中孫邕、中書侍郎王基薦寧曰：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-6', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '」乃遣新城太守州泰襲巫、秭歸、房陵，荊州刺史王基詣夷陵，昶詣江陵，兩岸引竹絙為橋，渡水擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-7', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '王基字伯輿，東萊曲城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-8', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '詔征南將軍王基部分諸軍，使烈督萬人徑造沮水，荊州、義陽南屯宜城，承書夙發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-9', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '晉室踐阼，下詔曰：「故司空王基旣著德立勳，又治身清素，不營產業，乆在重任，家無私積，可謂身沒行顯，足用勵俗者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-027-10', 'p0367', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-11', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍屯汝陽，使監軍王基督前鋒諸軍據南頓以待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-12', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '小人還項，復遇王基等十二軍，追尋毌丘，進兵討之，即時克破，所向全勝，要那後無繼何？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-13', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '是時鎮南將軍王基始至，督諸軍圍壽春，未合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-028-14', 'p0367', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '而未及安坐，喪王基之功，種惠吳人，結異類之情，寵鴦葬欽，忘疇昔之隙，不咎誕衆，使揚士懷愧，功高而人樂其成，業廣而敵懷其德，武昭旣敷，文筭又洽，推此道也，天下其孰能當之哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-029-15', 'p0367', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅往見安平太守王基，基令作卦，輅曰：「當有賤婦人生一男兒，墯地便走入竈中死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-029-16', 'p0367', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '輅別傳曰：王基即遣信都令遷掘其室中，入地八尺，果得二棺，一棺中有矛，一棺中有角弓及箭，箭乆遠，木皆消爛，但有鐵及角完耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-047-17', 'p0367', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-048-18', 'p0367', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '吳桓王基之以武，太祖成之以德，聦明睿達，懿度深遠矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-056-19', 'p0367', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '加討虜聦明神武，繼承洪業，攬結英雄，周濟世務，軍衆日盛，事業日隆，雖昔蕭王之在河北，無以加也，必克成王基，應運東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a04-064-20', 'p0367', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏鎮南將軍王基圍誕，欽等突圍入城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-21', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-22', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '儉、欽移入項城，帝遣荊州刺史王基進據南頓以逼儉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-23', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '石苞、王基並請攻之，帝曰：「誕之逆謀，非一朝一夕也，聚糧完守，外結吳人，自謂足據淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-002-24', 'p0367', 'jinshu', 'a05-002', '《晉書·卷二》', '四年夏六月，分荊州置二都督，王基鎮新野，州泰鎮襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0367-a05-006-25', 'p0367', 'jinshu', 'a05-006', '《晉書·卷六》', '詔曰：「昔我高祖宣皇帝誕應期運，廓開王基。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-001-0', 'p0368', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '王昶家誡曰「濟陰魏諷」，而此云沛人，未詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-1', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙未，征南將軍王昶渡江，掩攻吳，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-2', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月甲申，以征南將軍王昶為征南大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-3', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十一月，詔征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-4', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '漢晉春秋曰：毌丘儉、王昶聞東軍敗，各燒屯走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-5', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲戌，以征南大將軍王昶為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-004-6', 'p0368', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋八月甲戌，以驃騎將軍王昶為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-014-7', 'p0368', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '弈字伯益，見王昶家誡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-021-8', 'p0368', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '兖州刺史王昶請與相見，終日不得與言，昶歎賞之，自以不能測也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-021-9', 'p0368', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '征南大將軍王昶、征東將軍胡遵、鎮南將軍毌丘儉等表請征吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-022-10', 'p0368', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '遷為司空，固推驃騎將軍王昶、光祿大夫王觀、司隷校尉王祥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-11', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '魏名臣奏載黃門侍郎杜恕表，稱：「韓觀、王昶，信有兼才，高官重任，不但三州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-12', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '王昶字文舒，太原晉陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-13', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '其年為尚書，出為荊州刺史，加揚烈將軍，隨征南王昶擊吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-027-14', 'p0368', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-029-15', 'p0368', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '惟相司空王昶、征北將軍程喜、中領軍王肅有蹉跌云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-047-16', 'p0368', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，魏大將軍王昶圍南郡，荊州刺史王基攻西陵，遣將軍戴烈、陸凱往拒之，皆引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-048-17', 'p0368', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a04-056-18', 'p0368', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '明年，魏征南將軍王昶率衆攻江陵城，不克而退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0368-a05-002-19', 'p0368', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-004-0', 'p0369', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '四月，以司空高柔為司徒；光祿大夫徐邈為司空，固辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-008-1', 'p0369', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '州里徐邈責之曰：「不孝莫大於無後，何可終身不娶乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-014-2', 'p0369', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '如征東將軍滿寵、涼州刺史徐邈，並有譖毀之者，資皆盛陳其素行，使卒無纖介。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-024-3', 'p0369', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '及曁年過八十，起家就列；柔保官二十年，元老終位：比之徐邈、常林，於茲為疚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-4', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '徐邈字景山，燕國薊人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-5', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a04-027-6', 'p0369', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a05-019-7', 'p0369', 'jinshu', 'a05-019', '《晉書·卷十九》', '」祠部郎中徐邈議：「圓丘郊祀，繼典無二，宣皇帝嘗辯斯義，而檢以聖典。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0369-a05-042-8', 'p0369', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '刺史燕國徐邈有女才淑，擇夫未嫁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-003-0', 'p0370', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '孫權遣將朱然等二萬人圍江夏郡，荊州刺史胡質等擊之，然退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-014-1', 'p0370', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖徵曄及蔣濟、胡質等五人，皆揚州名士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-015-2', 'p0370', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和二年，帝使逵督前將軍滿寵、東莞太守胡質等四軍，從西陽直向東關，曹休從皖，司馬宣王從江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-022-3', 'p0370', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '蜀大將軍姜維率衆依麴山築二城，使牙門將句安、李歆等守之，聚羌胡質任等寇偪諸郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-4', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '故司空徐邈、征東將軍胡質、衞尉田豫皆服職前朝，歷事四世，出統戎馬，入贊庶政，忠清在公，憂國忘私，不營產業，身沒之後，家無餘財，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-5', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '胡質字文德，楚國壽春人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-027-6', 'p0370', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '評曰：徐邈清尚弘通，胡質素業貞粹，王昶開濟識度，王基學行堅白，皆掌統方任，垂稱著績。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-056-7', 'p0370', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '魏將蒲忠、胡質各將數千人，忠要遮險隘，圖斷然後，質為忠繼援。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0370-a04-056-8', 'p0370', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '孫氏異同評曰：魏志及江表傳云然以景初元年、正始二年再出為寇，所破胡質、蒲忠在景初元年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-011-0', 'p0371', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '論曰：周武王觀兵孟津，退而還師，以為紂未可伐，斯時有未至者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-036-1', 'p0371', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '史記曰，武王觀兵孟津，諸侯不期而至者八百人，皆曰：「紂可伐矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a03-057-2', 'p0371', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '是以先王觀象育物，敬授民時，象，天象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-004-3', 'p0371', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸亥，以尚書右僕射王觀為司空，冬十月，觀薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-022-4', 'p0371', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '遷為司空，固推驃騎將軍王昶、光祿大夫王觀、司隷校尉王祥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-024-5', 'p0371', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '王觀字偉臺，東郡廩丘人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-024-6', 'p0371', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '評曰：韓曁處以靜居行化，出以任職流稱；崔林簡樸知能；高柔明於法理；孫禮剛斷伉厲；王觀清勁貞白：咸克致公輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a04-063-7', 'p0371', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '昔聖王觀天地之文，以畫八卦之象，故亹亹成於蓍策，變化形乎六爻，是以三易雖殊，卦繇理一，安有迴轉一籌，可以鉤深測隱，意對逆占，而能遂知來物者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0371-a05-001-8', 'p0371', 'jinshu', 'a05-001', '《晉書·卷一》', '」命太僕王觀行中領軍，攝羲營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-003-0', 'p0372', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '西平麴英反，殺臨羌令、西都長，遣將軍郝昭、鹿磐討斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-003-1', 'p0372', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '魏略曰：先是使將軍郝昭築陳倉城；會亮至，圍昭，不能拔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-009-2', 'p0372', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '真以亮懲於祁山，後出必從陳倉，乃使將軍郝昭、王生守陳倉，治其城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0372-a04-016-3', 'p0372', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '又將軍郝昭、魏平先是各屯守金城，亦受詔不得西度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-033-0', 'p0373', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏將王雙率軍追亮，亮與戰，破之，斬雙，還漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-035-1', 'p0373', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏將王雙率騎追亮，亮與戰，破之，斬雙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-035-2', 'p0373', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '前年耀師，馘斬王雙；今歲爰征，郭淮遁走；降集氐、羌，興復二郡，威鎮凶暴，功勳顯然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0373-a04-056-3', 'p0373', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '仁果遣其子泰攻濡須城，分遣將軍常雕督諸葛虔、王雙等，乘油船別襲中洲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-005-0', 'p0374', 'jinshu', 'a05-005', '《晉書·卷五》', '王浚遣鮮卑文鴦帥騎救之，勒退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-039-1', 'p0374', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '永嘉中，石勒寇冀州，浚遣鮮卑文鴦討勒，勒走南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0374-a05-039-2', 'p0374', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '使者未及發，會洛京傾覆，浚大樹威令，專征伐，遣督護王昌、中山太守阮豹等，率諸軍及務勿塵世子疾陸眷、并弟文鴦、從弟末柸，攻石勒於襄國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0375-a03-085-0', 'p0375', 'houhanshu', 'a03-085', '《後漢書·卷八十五》', '山海經曰：「君子國衣冠帶劔，食獸，使二文虎在旁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0375-a03-119-1', 'p0375', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」文虎伏軾，魏都賦注曰：「軾，車橫覆膝，人所馮止者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-034-0', 'p0376', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '故太保衛瓘本爵菑陽縣公，既被橫害，乃進茅土，始贈蘭陵，又轉江夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-039-1', 'p0376', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '先是，勖啟「伐蜀，宜以衛瓘爲監軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-039-2', 'p0376', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '尚書令衛瓘、吏部尚書山濤皆可爲司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0376-a05-040-3', 'p0376', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '及楚王瑋矯詔害汝南王亮、太保衛瓘，詔使模將中騶二百人救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a03-096-0', 'p0377', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」晉起居注曰：「太尉賈充薨，皇太子妃之父，又太保也，有司奏依漢元明二帝親臨師保故事，皇太子素服為發哀，又臨其喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-1', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '中護軍賈充又逆帝戰於南闕下，帝自用劒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-2', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　干寶晉紀曰：成濟問賈充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-3', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '賈充自外而入，帝師潰散，猶稱天子，手劒奮擊，衆莫敢逼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-004-4', 'p0377', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏末傳曰：賈充呼帳下督成濟謂曰：「司馬家事若敗，汝等豈復有種乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-010-5', 'p0377', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '與賈充共定音律，又作易集解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-022-6', 'p0377', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」對曰：「誅賈充以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-022-7', 'p0377', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」泰曰：「獨有斬賈充，少可以謝天下耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-8', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：司馬文王旣秉朝政，長史賈充以為宜遣參佐慰勞四征，於是遣充至壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-9', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '魏末傳曰：賈充與誕相見，談說時事，因謂誕曰：「洛中諸賢，皆願禪代，君所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-10', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會得文王書云：「恐鄧艾或不就徵，今遣中護軍賈充將步騎萬人徑入斜谷，屯樂城，吾自將十萬屯長安，相見在近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-028-11', 'p0377', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '晏旣用賈充、裴秀、朱整，又議用弼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-033-12', 'p0377', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '王謂賈充曰：「人之無情，乃可至於是乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-048-13', 'p0377', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」旣至，車騎將軍賈充、尚書令裴秀、侍中荀勗等欲傲以所不知而不能屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a04-048-14', 'p0377', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-15', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '沈、業馳告于帝，帝召護軍賈充等為之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-16', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '相府兵將止不敢戰，賈充叱諸將曰：「公畜養汝輩，正為今日耳！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-17', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '」泰曰：「惟腰斬賈充，微以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-18', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '是時魏諸王侯悉在鄴城，命從事中郎山濤行軍司事，鎮於鄴，遣護軍賈充持節、督諸軍，據漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-002-19', 'p0377', 'jinshu', 'a05-002', '《晉書·卷二》', '秋七月，帝奏司空荀顗定禮儀，中護軍賈充正法律，尚書僕射裴秀議官制，太保鄭沖總而裁焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-20', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '」九月戊午，以魏司徒何曾為丞相，鎮南將軍王沈為御史大夫，中護軍賈充為衞將軍，議郎裴秀為尚書令、光祿大夫，皆開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-21', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以驃騎將軍石苞為大司馬，封樂陵公，車騎將軍陳騫為高平公，衞將軍賈充為車騎將軍、魯公，尚書令裴秀為鉅鹿公，侍中荀勗為濟北公，太保鄭冲為太傅、壽光公，太尉王祥為太保、睢陵公，丞相何曾為太尉、朗陵公，御史大夫王沈為驃騎將軍、愽陵公，司空荀顗為臨淮公，鎮北大將軍衞瓘為菑陽公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-22', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '秋七月癸酉，以車騎將軍賈充為都督秦、涼二州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-23', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '秋七月，以車騎將軍賈充為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-24', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以故太傅鄭沖、太尉荀顗、司徒石苞、司空裴秀、驃騎將軍王沈、安平獻王孚等及太保何曾、司空賈充、太尉陳騫、中書監荀勗、平南將軍羊祜、齊王攸等皆列於銘饗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-25', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '己亥，以太保何曾為太傅，太尉陳騫為大司馬，司空賈充為太尉，鎮軍大將軍齊王攸為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-26', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '以太尉賈充為大都督，行冠軍將軍楊濟為副，總統衆軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-27', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-28', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '夏四月庚午，太尉、魯公賈充薨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-003-29', 'p0377', 'jinshu', 'a05-003', '《晉書·卷三》', '況以新習易動之基，而無久安難拔之慮，故賈充凶豎，懷姦志以擁權；楊駿豺狼，苞禍心以專輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-005-30', 'p0377', 'jinshu', 'a05-005', '《晉書·卷五》', '察庾純、賈充之爭，而見師尹之多僻；考平吳之功，而知將帥之不讓；思郭欽之謀，而寤戎狄有釁；覽傅玄、劉毅之言，而得百官之邪；核傅咸之奏、錢神之論，而覩寵賂之彰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-31', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」時王佑、賈充、裴秀皆前朝名望，祜每讓，不處其右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-32', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '暨弟伊，初爲車騎賈充掾，後歷平南將軍、都督江北諸軍事，鎮宛，爲張昌所殺，追贈鎮南將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-034-33', 'p0377', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '與車騎將軍賈充等定律令，既成，預爲之注解，乃奏之曰：「法者，蓋繩墨之斷例，非窮理盡性之書也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-036-full-34', 'p0377', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '眾軍既進，而未有克獲，賈充等奏誅華以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-036-35', 'p0377', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '眾軍既進，而未有克獲，賈充等奏誅華以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-36', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈以才望，顯名當世，是以創業之事，羊祜、荀勖、裴秀、賈充等，皆與沈諮謀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-37', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '顗明三禮，知朝廷大儀，而無質直之操，唯阿意苟合於荀勖、賈充之間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-38', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '初，皇太子將納妃，顗上言賈充女姿德淑茂，可以參選，以此獲譏於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-39', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '拜中書監，加侍中，領著作，與賈充共定律令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-40', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及王濬表請伐吳，勖與賈充固諫不可，帝不從，而吳果滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-41', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」時太尉賈充、司徒李胤並薨，太子太傅又缺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-42', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '承顏悅色，寵愛日隆，賈充、荀勖並與之親善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-039-43', 'p0377', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '初謀伐吳，紞與賈充、荀勖同共苦諫不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-44', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '賈充字公閭，平陽襄陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-45', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '車騎將軍賈充，獎明聖意，諮詢善道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-46', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '侍中、守尚書令、車騎將軍賈充，雅量弘高，達見明遠，武有折衝之威，文懷經國之慮，信結人心，名震域外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-47', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '美姿貌，善容止，賈充辟爲司空掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-48', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '與賈充素相親遇，充妻待彰若同生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-040-49', 'p0377', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '史臣曰：賈充以諂諛陋質，刀筆常材，幸屬昌辰，濫叨非據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0377-a05-042-50', 'p0377', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '賈充、荀勖陳諫以爲不可，唯張華固勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-074-0', 'p0378', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '張華云：「望夷之宮在長陵西北長平觀，東臨涇水，作之以望北夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-080-1', 'p0378', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '張華博物志曰：「王子山與父叔師到泰山從鮑子真學筭，到魯賦靈光殿，歸度湘水溺死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-093-2', 'p0378', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '天誘其衷，得備著作郎，建言十志皆當撰錄，遂與議郎張華等分受之，其難者皆以付臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-096-3', 'p0378', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '司空張華以問博士束皙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a03-110-4', 'p0378', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '邯鄲張華曰：「趙奢冢在邯鄲西山上，謂之馬服山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-001-5', 'p0378', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張華博物志曰：漢世，安平崔瑗、瑗子寔、弘農張芝、芝弟昶並善草書，而太祖亞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-014-6', 'p0378', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '與張華六人，並稱文辭可觀，意思詳序。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-022-7', 'p0378', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '同郡張華，家單少孤，不為鄉邑所知，惟欽貴異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-022-8', 'p0378', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '晉諸公贊曰：張華博識多聞，無物不知。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-026-9', 'p0378', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '後張華請為長史，稍遷至尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-045-10', 'p0378', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '後失荀勗、張華指，左遷漢中太守，諸王多以為冤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-047-11', 'p0378', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '司空張華辟，未就，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a04-058-12', 'p0378', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '機雲別傳曰：晉太康末，俱入洛，造司空張華，華一見而奇之，曰：「伐吳之役，利在獲二儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-003-13', 'p0378', 'jinshu', 'a05-003', '《晉書·卷三》', '甲午，以尚書張華都督幽州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-004-14', 'p0378', 'jinshu', 'a05-004', '《晉書·卷四》', '以中書監張華為司空，太尉、隴西王泰為尚書令，衞將軍、梁王肜為太子太保。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-004-15', 'p0378', 'jinshu', 'a05-004', '《晉書·卷四》', '癸巳，梁王肜、趙王倫矯詔廢賈后為庶人，司空張華、尚書僕射裴頠皆遇害，侍中賈謐及黨與數十人皆伏誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-012-16', 'p0378', 'jinshu', 'a05-012', '《晉書·卷十二》', '」後賈后陷殺太子，趙王廢后，又殺之，斬張華、裴頠，遂篡位，廢帝為太上皇，天下從此遘亂連禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-17', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是月，賈后殺太子，趙王倫尋廢殺后，斬司空張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-18', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '後五年，司空張華遇禍，賈后廢死，魯公賈謐誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-013-19', 'p0378', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是月賈后殺太子，趙王倫尋廢殺后，斬司空張華，又廢帝自立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-016-20', 'p0378', 'jinshu', 'a05-016', '《晉書·卷十六》', '泰始十年，中書監荀勗、中書令張華出御府銅竹律二十五具，部太樂郎劉秀等校試，其三具與杜夔及左延年律法同，其二十二具，視其銘題尺寸，是笛律也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-21', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '帝以其病，不宜常入，遣中書令張華問其籌策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-22', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '時帝密有滅吳之計，而朝議多違，唯預、羊祜、張華與帝意合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-034-23', 'p0378', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」時帝與中書令張華圍棋，而預表適至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-24', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '張華字茂先，范陽方城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-25', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-26', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '後倫、秀伏誅，齊王冏輔政，摯虞致箋於冏曰：「間於張華沒後入中書省，得華先帝時答詔本草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-27', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '張華、裴頠各以見憚取誅於時，解系、解結同以羔羊並被其害，歐陽建等無罪而死，百姓憐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-28', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '以計干張華而不見用，益以不平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-full-29', 'p0378', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '衞瓘撫武帝之牀，張華距趙倫之命，進諫則伯玉居多，臨危則茂先爲美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-30', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '張華字茂先，范陽方城人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-31', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '及吳滅，詔曰：「尚書、關內侯張華，前與故太傅羊祜共創大計，遂典掌軍事，部分諸方，算定權略，運籌決勝，有謀謨之勳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-32', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '後倫、秀伏誅，齊王冏輔政，摯虞致箋於冏曰：「間於張華沒後入中書省，得華先帝時答詔本草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-33', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '張華、裴頠各以見憚取誅於時，解系、解結同以羔羊並被其害，歐陽建等無罪而死，百姓憐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-34', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '以計干張華而不見用，益以不平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-036-35', 'p0378', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '衞瓘撫武帝之牀，張華距趙倫之命，進諫則伯玉居多，臨危則茂先爲美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-039-36', 'p0378', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '俄領祕書監，與中書令張華依劉向別錄，整理記籍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-039-37', 'p0378', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '吳平，紞內懷慚懼，疾張華如讎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-38', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '雖腰斬張華，不足以謝天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-39', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '於是事下三府，司徒王戎、司空張華、領軍將軍王衍、侍中樂廣、黃門侍郎嵇紹、國子博士謝衡皆從謐議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-40', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '今吳寇當平，汝方表斬張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-41', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '模乃盡心匡弼，推張華、裴頠同心輔政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-040-42', 'p0378', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '珧臨刑稱冤，云：「事在石函，可問張華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0378-a05-042-43', 'p0378', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '賈充、荀勖陳諫以爲不可，唯張華固勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a03-054-0', 'p0379', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '其夜有黃衣童子向寶再拜曰：『我西王母使者，君仁愛救拯，實感成濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-1', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '衆欲退，太子舍人成濟問充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-2', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　干寶晉紀曰：成濟問賈充曰：「事急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-3', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '充帥厲將士，騎督成倅弟成濟以矛進，帝崩于師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-4', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏末傳曰：賈充呼帳下督成濟謂曰：「司馬家事若敗，汝等豈復有種乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-5', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '皇太后令曰：「吾以不德，遭家不造，昔援立東海王子髦，以為明帝嗣，見其好書疏文章，兾可成濟，而情性暴戾，日月滋甚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-004-6', 'p0379', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」魏氏春秋曰：成濟兄弟不即伏罪，袒而升屋，醜言悖慢；自下射之，乃殪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a04-021-7', 'p0379', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '山濤啟以為祕書郎，稱紹平簡溫敏，有文思，又曉音，當成濟者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-002-8', 'p0379', 'jinshu', 'a05-002', '《晉書·卷二》', '」太子舍人成濟抽戈犯蹕，刺之，刃出於背，天子崩于車中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-002-9', 'p0379', 'jinshu', 'a05-002', '《晉書·卷二》', '」於是歸罪成濟而斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-013-10', 'p0379', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年五月，有成濟之變及諸葛誕誅，皆其應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-013-11', 'p0379', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年，高貴鄉公為成濟所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0379-a05-040-12', 'p0379', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '初，充母柳見古今重節義，竟不知充與成濟事，以濟不忠，數追罵之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0380-a04-005-0', 'p0380', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '文昭甄皇后，中山無極人，明帝母，漢太保甄邯後也，世吏二千石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-029-0', 'p0381', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '及郭皇后廢，建武十七年廢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-042-1', 'p0381', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '光武皇帝十一子：郭皇后生東海恭王彊、沛獻王輔、濟南安王康、阜陵質王延、中山簡王焉，許美人生楚王英，光烈皇后生顯宗、東平憲王蒼、廣陵思王荊、臨淮懷公衡、琅邪孝王京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-100-2', 'p0381', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '是時郭皇后已疏，至十七年十月，遂廢為中山太后，立陰貴人為皇后，除宮之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a03-108-3', 'p0381', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '其十月，廢郭皇后，詔曰「不可以奉供養」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a04-005-4', 'p0381', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '文德郭皇后，安平廣宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0381-a04-005-5', 'p0381', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明元郭皇后，西平人也，世河右大族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0382-a04-005-0', 'p0382', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '明悼毛皇后，河內人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0383-a04-028-0', 'p0383', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，吳大將全琮，孫權之婚親重臣也，琮子懌、孫靜、從子端、翩、緝等，皆將兵來救誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0383-a04-051-1', 'p0383', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫靜字幼臺，堅季弟也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0384-a04-032-0', 'p0384', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」權不聽，遣孫瑜率水軍住夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0384-a04-054-1', 'p0384', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '十一年，督孫瑜等討麻、保二屯，梟其渠帥，囚俘萬餘口，還備官亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-046-0', 'p0385', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '盡更置長吏，策自領會稽太守，復以吳景為丹楊太守，以孫賁為豫章太守；分豫章為廬陵郡，以賁弟輔為廬陵太守，丹楊朱治為吳郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-046-1', 'p0385', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '書授孫賁以長沙，業張津以零、桂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-049-2', 'p0385', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '欲南渡江，吳景、孫賁迎置曲阿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0385-a04-050-3', 'p0385', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '會景為劉繇所迫，復北依術，術以為督軍中郎將，與孫賁共討樊能、于麋於橫江，又擊笮融、薛禮於秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a03-069-0', 'p0386', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '武孫輔，時年二歲，逃竄得全。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a04-051-1', 'p0386', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫輔字國儀，賁弟也，以揚武校尉佐孫策平三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a04-063-2', 'p0386', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '遭亂避地，客遊廬陵，事孫輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a05-004-3', 'p0386', 'jinshu', 'a05-004', '《晉書·卷四》', '倫遣其將閭和出伊闕，張泓、孫輔出堮坂以距囧，孫會、士猗、許超出黃橋以距穎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0386-a05-004-4', 'p0386', 'jinshu', 'a05-004', '《晉書·卷四》', '囧將何勗、盧播擊張泓於陽翟，大破之，斬孫輔等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-050-0', 'p0387', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '吳主權步夫人，臨淮淮陰人也，與丞相隲同族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-050-1', 'p0387', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及步夫人薨，權欲立之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0387-a04-059-2', 'p0387', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '初，登所生庶賤，徐夫人少有母養之恩，後徐氏以妬廢處吳，而步夫人最寵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a03-047-0', 'p0391', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '前書曰，漢遣公主為烏孫夫人，結為昆弟，則是斷匈奴右臂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-034-1', 'p0391', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '先主旣定益州，而孫夫人還吳，漢晉春秋云：先主入益州，吳遣迎孫夫人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-036-2', 'p0391', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '此時先主孫夫人以權妹驕豪，多將吳吏兵，縱橫不法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0391-a04-037-3', 'p0391', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」亮荅曰：「主公之在公安也，北畏曹公之彊，東憚孫權之逼，近則懼孫夫人生變於肘腋之下；當斯之時，進退狼跋，法孝直為之輔翼，令翻然翱翔，不可復制，如何禁止法正使不得行其意邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0393-a04-045-0', 'p0393', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '－－贊糜芳、士仁、郝普、潘濬糜芳字子方，東海人也，為南郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0393-a04-047-1', 'p0393', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '六月，權令將軍賀齊督糜芳、劉邵等襲蘄春，邵等生虜宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0394-a04-036-0', 'p0394', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '又南郡太守麋芳在江陵，將軍傅士仁屯公安，素皆嫌羽自輕己。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-026-0', 'p0395', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '姜維出石營，從彊川，乃西迎治無戴，留陰平太守廖化於成重山築城，斂破羌保質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-026-1', 'p0395', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '比歲以來，摧破廖化，禽虜句安，功績顯著，朕甚嘉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-2', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '三日，維遣廖化自白水南向艾結營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-3', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '未到，聞其已破，退趣白水，與蜀將張翼、廖化等合守劒閣拒會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-028-4', 'p0395', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-033-5', 'p0395', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-043-6', 'p0395', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '華陽國志曰：後張翼、廖化並為大將軍，時人語曰：「前有王、句，後有張、廖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-044-7', 'p0395', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-044-8', 'p0395', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-9', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時都護諸葛瞻初統朝事，廖化過預，欲與預共詣瞻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-10', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '廖化字元儉，本名淳，襄陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a04-045-11', 'p0395', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '漢晉春秋曰：景耀五年，姜維率衆出狄道，廖化曰：「『兵不戢，必自焚』，伯約之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0395-a05-002-12', 'p0395', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-035-0', 'p0396', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮卒後，稍遷至尚書僕射，代陳祗為尚書令，遷大將軍，平臺事，而義陽樊建代焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-036-1', 'p0396', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-039-2', 'p0396', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '陳祗代允為侍中，與黃皓互相表裏，皓始預政事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0396-a04-042-3', 'p0396', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '于時軍旅數出，百姓彫瘁，周與尚書令陳祗論其利害，退而書之，謂之仇國論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-028-0', 'p0397', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會上言曰：「賊姜維、張翼、廖化、董厥等逃死遁走，欲趣成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-033-1', 'p0397', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '於是遣左右車騎將軍張翼、廖化、輔國大將軍董厥等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-2', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '景耀四年，為行都護衞將軍，與輔國大將軍南鄉侯董厥並平尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-3', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '董厥者，丞相亮時為府令史，亮稱之曰：「董令史，良士也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-035-4', 'p0397', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '案晉百官表：董厥字龔襲，亦義陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0397-a04-044-5', 'p0397', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-033-0', 'p0398', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '尚書令樊建、侍中張紹、光祿大夫譙周、祕書令郤正、殿中督張通並封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-1', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮卒後，稍遷至尚書僕射，代陳祗為尚書令，遷大將軍，平臺事，而義陽樊建代焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-2', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '權問諸葛恪曰：「樊建何如宗預也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-035-3', 'p0398', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '漢晉春秋曰：樊建為給事中，晉武帝問諸葛亮之治國，建對曰：「聞惡必改，而不矜過，賞罰之信，足感神明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0398-a04-045-4', 'p0398', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '少子武，有文，與樊建齊名，官亦至尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-032-0', 'p0399', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '是後在所並言衆瑞，日月相屬，故議郎陽泉侯劉豹、青衣侯向舉、偏將軍張裔 ‧ 黃權、大司馬屬殷純、益州別駕從事趙莋、治中從事楊洪、從事祭酒何宗、議曹從事杜瓊、勸學從事張爽、尹默、譙周等上言：「臣聞河圖、洛書，五經讖、緯，孔子所甄，驗應自遠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-035-1', 'p0399', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '今使使持節左中郎將杜瓊，贈君丞相武鄉侯印綬，謚君為忠武侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-042-2', 'p0399', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '杜瓊字伯瑜，蜀郡成都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-042-3', 'p0399', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '周羣占天有徵，杜瓊沈默慎密，諸生之純也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0399-a04-045-4', 'p0399', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '事廣漢任安學，精究安術，與杜瓊同師而名問過之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0400-a04-042-0', 'p0400', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '時又有魏郡胡潛，字公興，不知其所以在益土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0402-a04-045-0', 'p0402', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0402-a04-045-1', 'p0402', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '襄陽記曰：楊顒字子昭，楊儀宗人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-017-0', 'p0404', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '備遣陳式等十餘營絕馬鳴閣道，晃別征破之，賊自投山谷，多死者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-032-1', 'p0404', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二年春正月，先主軍還秭歸，將軍吳班、陳式水軍屯夷陵，夾江東西岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0404-a04-033-2', 'p0404', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '七年春，亮遣陳式攻武都、陰平，遂克定二郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-032-0', 'p0405', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫權遣書請和，先主盛怒不許，吳將陸議、李異、劉阿等屯巫、秭歸；將軍吳班、馮習自巫攻破異等，軍次秭歸，武陵五谿蠻夷遣使請兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-032-1', 'p0405', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '二年春正月，先主軍還秭歸，將軍吳班、陳式水軍屯夷陵，夾江東西岸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-035-2', 'p0405', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮使魏延、高翔、吳班赴拒，大破之，獲甲首三千級、玄鎧五千領、角弩三千一百張，宣王還保營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-040-3', 'p0405', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '輙與行中軍師車騎將軍都鄉侯臣劉琰，使持節前軍師征西大將軍領涼州刺史南鄭侯臣魏延、前將軍都亭侯臣袁綝、左將軍領荊州刺史高陽鄉侯臣吳壹、督前部右將軍玄鄉侯臣高翔、督後部後將軍安樂亭侯臣吳班、領長史綏軍將軍臣楊儀、督左部行中監軍揚武將軍臣鄧芝、行前監軍征南將軍臣劉巴、行中護軍偏將軍臣費禕、行前護軍偏將軍漢成亭侯臣許允、行左護軍篤信中郎將臣丁咸、行右護軍偏將軍臣劉敏、行護軍征南將軍當陽亭侯臣姜維、行中典軍討虜將軍臣上官雝、行中參軍昭武中郎將臣胡濟、行參軍建議將軍臣閻晏、行參軍偏將軍臣爨習、行參軍裨將軍臣杜義、行參軍武略中郎將臣杜祺、行參軍綏戎都尉臣盛勃、領從事中郎武略中郎將臣樊岐等議，輙解平任，免官祿、節傳、印綬、符策，削其爵土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0405-a04-058-4', 'p0405', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備從巫峽、建平、連平、連圍至夷陵界，立數十屯，以金錦爵賞誘動諸夷，使將軍馮習為大督，張南為前部，輔匡、趙融、廖淳、傅肜等各為別督，先遣吳班將數千人於平地立營，欲以挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-064-0', 'p0406', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '先是陳留邊鳳為京兆尹，亦有能名，郡人為之語曰：「前有趙張三王，前書，趙廣漢、張敞、王遵、王章、王駿俱為京兆尹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-076-1', 'p0406', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '趙謂趙廣漢，張謂張敞者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0406-a03-077-2', 'p0406', 'houhanshu', 'a03-077', '《後漢書·卷七十七》', '又趙廣漢為京兆尹，侵犯貴戚大臣，將吏卒入丞相魏相府，召其夫人跪庭下受辭，責以殺婢事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0407-a04-028-0', 'p0407', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '忠、纂馳還更戰，大破之，斬瞻及尚書張遵等首，進軍到雒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-0', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-1', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：蔣舒將出降，乃詭謂傅僉曰：「今賊至不擊而閉城自守，非良圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0410-a04-044-2', 'p0410', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '蜀記曰：蔣舒為武興督，在事無稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-044-0', 'p0411', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-044-1', 'p0411', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '漢晉春秋曰：蔣舒將出降，乃詭謂傅僉曰：「今賊至不擊而閉城自守，非良圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0411-a04-045-2', 'p0411', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '蜀記載晉武帝詔曰：「蜀將軍傅僉，前在關城，身拒官軍，致死不顧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a04-028-0', 'p0412', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蜀監軍王含守樂城，護軍蔣斌守漢城，兵各五千。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a04-044-1', 'p0412', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '於是令督漢中胡濟却住漢壽，監軍王含守樂城，護軍蔣斌守漢城，又於西安、建威、武衞、石門、武城、建昌、臨遠皆立圍守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0412-a05-002-2', 'p0412', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會分為二隊，入自斜谷，使李輔圍王含於樂城，又使部將易愷攻蔣斌於漢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0414-a04-056-0', 'p0414', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '績與奮威將軍諸葛融書曰：「昶遠來疲困，馬無所食，力屈而走，此天助也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-027-0', 'p0415', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '會吳遣朱異來救誕，軍於安城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-1', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽雖在他國，不能屈節下人，自呂據、朱異等諸大將皆憎疾之，惟峻常左右之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-2', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吴將朱異再以大衆來迎誕等，渡黎漿水，泰等逆與戰，每摧其鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-028-3', 'p0415', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-047-4', 'p0415', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏將文欽偽叛以誘朱異，權遣呂據就異以迎欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-5', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三月，使鎮南將軍朱異襲安豐，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-6', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '八月，先遣欽及驃騎呂據、車騎劉纂、鎮南朱異、前將軍唐咨軍自江都入淮、泗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-7', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '朱異自虎林率衆襲夏口，夏口督孫壹奔魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-8', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '秋七月，綝率衆救壽春，次于鑊里，朱異至自夏口，綝使異為前部督，與丁奉等將介士五萬解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-048-9', 'p0415', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '朱異以軍士乏食引還，綝大怒，九月朔己巳，殺異於鑊里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-055-10', 'p0415', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '遣朱異、唐咨等往救，復使奉與黎斐解圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-056-11', 'p0415', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '朱然攻樊，據與朱異破城外圍，還拜偏將軍，入補馬閑右部督，遷越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-056-12', 'p0415', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-13', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '將軍朱異有所是非，恪怒，立奪其兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-14', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '其明年，文欽說峻征魏，峻使欽與呂據、車騎劉纂、鎮南朱異、前將軍唐咨自江都入淮、泗，以圖青、徐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-15', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '朱異帥三萬人屯安豐城，為文欽勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a04-064-16', 'p0415', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '又委罪朱異，擅殺功臣，不先表聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a05-002-17', 'p0415', 'jinshu', 'a05-002', '《晉書·卷二》', '八月，吳將朱異帥兵萬餘人，留輜重於都陸，輕兵至黎漿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0415-a05-002-18', 'p0415', 'jinshu', 'a05-002', '《晉書·卷二》', '奇兵震擊，而朱異摧破；神變應機，而全琮稽服；取亂攻昧，而高墉不守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-004-0', 'p0416', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '偽將施績，賊之名臣，懷疑自猜，深見忌惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-027-1', 'p0416', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '於是昶使積弩同時俱發，賊大將施績夜遁入江陵城，追斬數百級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-027-2', 'p0416', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，昶據夾石以逼江陵，持施績、全熈使不得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-3', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '甲申，使大將軍丁奉督諸軍向魏壽春，將軍留平別詣施績於南郡，議兵所向，將軍丁封、孫異如沔中，皆救蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-4', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '元興元年八月，以上大將軍施績、大將軍丁奉為左右大司馬，張布為驃騎將軍，加侍中，諸增位班賞，一皆如舊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-5', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '夏四月，左大司馬施績卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-048-6', 'p0416', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '大司馬陸公以文武熈朝，左丞相陸凱以謇諤盡規，而施績、范慎以威重顯，丁奉、鍾離斐以武毅稱，孟宗、丁固之徒為公卿，樓玄、賀劭之屬掌機事，元首雖病，股肱猶良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-051-7', 'p0416', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '孫峻之誅諸葛恪也，壹與全熈、施績攻恪弟公安督融，融自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-052-8', 'p0416', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '恪旣誅，遣無難督施寬就將軍施績、孫壹、全熈等取融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-056-9', 'p0416', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '評曰：朱治、呂範以舊臣任用，朱然、朱桓以勇烈著聞，呂據、朱異、施績咸有將領之才，克紹堂構。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-058-10', 'p0416', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '建衡二年，大司馬施績卒，拜抗都督信陵、西陵、夷道、樂鄉，公安諸軍事，治樂鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-059-11', 'p0416', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '丞相陸遜、大將軍諸葛恪、太常顧譚、驃騎將軍朱據、會稽太守滕胤、大都督施績、尚書丁密等奉禮而行，宗事太子，驃騎將軍步隲、鎮南將軍呂岱、大司馬全琮、左將軍呂據、中書令孫弘等附魯王，中外官僚將軍大臣舉國中分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a04-060-12', 'p0416', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '盛以施績、留平，智略名將，屢經於彼，無云當城之者，不然徇計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a05-003-13', 'p0416', 'jinshu', 'a05-003', '《晉書·卷三》', '」冬十月，吳將施績入江夏，萬郁寇襄陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0416-a05-037-14', 'p0416', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '吳將施績寇江夏，邊境騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-048-0', 'p0417', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '姊全公主嘗譖太子和子母，心不自安，因倚權意，欲豫自結，數稱述全尚女，勸為亮納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-048-1', 'p0417', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '亮以綝專恣，與太常全尚，將軍劉丞謀誅綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-050-2', 'p0417', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '孫亮全夫人，全尚女也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-050-3', 'p0417', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '全尚妻即峻姊，故惟全主祐焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-4', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝入諫不從，亮遂與公主魯班、太常全尚、將軍劉承議誅綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-5', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '綝率衆夜襲全尚，遣弟恩殺劉承於蒼龍門外，遂圍宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-6', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '江表傳曰：亮召全尚息黃門侍郎紀密謀，曰：「孫綝專勢，輕小於孤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0417-a04-064-7', 'p0417', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '太常全尚，累世受恩，不能督諸宗親，而全端等委城就魏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-0', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '」八月，以軍師張悌為丞相，牛渚都督何植為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-1', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '預又斬江陵督伍延，渾復斬丞相張悌、丹楊太守沈瑩等，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-2', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：吳丞相軍師張悌、護軍孫震、丹楊太守沈瑩帥衆三萬濟江，圍成陽都尉張喬於楊荷橋，衆才七千，閉柵自守，舉白接告降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-3', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '人問之，榮曰：「上天北斗門下卒見人縛張悌，意中大愕，不覺大呼，言『何以縛張軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-048-4', 'p0419', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '聞晉大衆，遠來臨江，庶竭勞瘁，衆皆摧退，而張悌不反，喪軍過半。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-051-5', 'p0419', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '震後禦晉軍，與張悌俱死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a04-061-6', 'p0419', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '姚信、樓玄、賀卲、張悌、郭逴、薛瑩、滕脩及族弟喜、抗，或清白忠勤，或姿才卓茂，皆社稷之楨幹，國家之良輔，願陛下重留神思，訪以時務，各盡其忠，拾遺萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-003-7', 'p0419', 'jinshu', 'a05-003', '《晉書·卷三》', '王渾、周浚與吳丞相張悌戰于版橋，大破之，斬悌及其將孫震、沈瑩，傳首洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-8', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '吳丞相張悌、大將軍孫震等率眾數萬指城陽，渾遣司馬孫疇、揚州刺史周浚擊破之，臨陣斬二將，及首虜七千八百級，吳人大震。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-9', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '又摧大敵，獲張悌，使皓塗窮勢盡，面縛乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0419-a05-042-10', 'p0419', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '」王渾久破皓中軍，斬張悌等，頓兵不敢進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0420-a04-048-0', 'p0420', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三月丙寅，殿中親近數百人叩頭請皓殺岑昏，皓惶憒從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0420-a04-053-1', 'p0420', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '尚書岑昏率公卿已下百餘人，詣宮叩頭請，尚罪得減死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-0', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '秋七月，太中大夫陳蕃為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-1', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '陳蕃等上疏諫曰『唯善政可以已之』，書奏不省。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-007-2', 'p0421', 'houhanshu', 'a03-007', '《後漢書·卷七》', '自非忠賢力爭，屢折姦鋒，忠賢謂李膺、陳蕃、竇武、黃瓊、朱穆、劉淑、劉陶等，各上書極諫，以折宦官等姦謀之鋒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-full-3', 'p0421', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-full-4', 'p0421', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-5', 'p0421', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以前太尉陳蕃為太傅，與竇武及司徒胡廣參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-008-6', 'p0421', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月丁亥，中常侍曹節矯詔誅太傅陳蕃、大將軍竇武及尚書令尹勳、侍中劉瑜、屯騎校尉馮述，皆夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-009-7', 'p0421', 'houhanshu', 'a03-009', '《後漢書·卷九》', '遣使弔祠故太傅陳蕃、大將軍竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-026-8', 'p0421', 'houhanshu', 'a03-026', '《後漢書·卷二十六》', '靈帝即位，中常侍曹節以陳蕃、竇氏旣誅，海內多怨，欲借寵時賢以為名，假借時賢寵榮以求美名，用解怨謗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-027-9', 'p0421', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '會病卒，謝承書曰：「靈帝即位，典與竇武、王暢、陳蕃等謀共誅中常侍曹節、侯覽、趙忠等，皆下獄自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-10', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '其憲章朝右，簡覈才職，委功曹陳蕃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-11', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '後太傅陳蕃辟，不應，為郡五官掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-031-12', 'p0421', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '謂委任功曹陳蕃、主簿應嗣，郡中大化也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-037-13', 'p0421', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝即位，太傅陳蕃、大將軍竇武輔政，復徵用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-039-14', 'p0421', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '會司隷校尉李膺等抵罪，而南陽太守成瑨、太原太守劉瓆下獄當死，茂與太尉陳蕃、司徒劉矩共上書訟之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-039-15', 'p0421', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '靈帝初，太傅陳蕃、大將軍竇武為宦者所誅，咨乃謝病去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-044-16', 'p0421', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '靈帝立，與太傅陳蕃參錄尚書事，復封故國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-044-17', 'p0421', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '與故吏陳蕃、李咸並為三司。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-045-18', 'p0421', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '歲餘，復代陳蕃為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-048-19', 'p0421', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '」對曰：「尚書令陳蕃任事則化，中常侍黃門豫政則亂，是以知陛下可與為善，可與為非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-20', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '」同郡陳蕃、周舉常相謂曰：「時月之閒不見黃生，則鄙吝之萌復存乎心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-21', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '時陳蕃為太守，以禮請署功曹，稺不免之，旣謁而退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-22', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '延熹二年，尚書令陳蕃、僕射胡廣等上疏薦稺等曰：「臣聞善人天地之紀，政之所由也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-053-23', 'p0421', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '中常侍曹節等專執朝事，新誅太傅陳蕃、大將軍竇武，欲借寵賢德，以釋衆望，乃白徵肱為太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-24', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '政崇溫和，好才愛士，引進郡人黃憲、陳蕃等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-25', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太尉陳蕃薦暢清方公正，有不可犯之色，禮記曰：「介冑之士，則有不可犯之色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-056-26', 'p0421', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '太后本遷南宮雲臺，太后父竇武與陳蕃謀誅宦官，反為中常侍曹節矯詔殺武、蕃，遷太后焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-27', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '二十餘年，靈帝即位，大將軍竇武、太傅陳蕃輔政，徵拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-28', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '大鴻臚陳蕃上疏救雲曰：「李雲所言，雖不識禁忌，干上逆旨，其意歸於忠國而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-057-29', 'p0421', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '又故太傅陳蕃，輔相陛下，勤身王室，夙夜匪懈，而見陷羣邪，一旦誅滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-30', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '於是濟陰太守胡廣等十餘人皆坐謬舉免黜，唯汝南陳蕃、潁川李膺、下邳陳球等三十餘人得拜郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-31', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '時陳蕃為光祿勳，深相敬待，數與議事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-32', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後陳蕃被徵，而言事者多訟韙，復拜議郎，遷尚書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-061-33', 'p0421', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '陳蕃、楊秉處稱賢宰，皇甫、張、段出號名將，王暢、李膺彌縫衮闕，彌縫猶補合也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-34', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '前太尉陳蕃、劉矩，漢官儀曰：「矩字叔方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-35', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '時竇太后臨朝，大將軍竇武與太傅陳蕃謀誅宦官，事泄，中常侍曹節等於中作亂，以奐新徵，不知本謀，矯制使奐與少府周靖率五營士圍武。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-36', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '故大將軍竇武、太傅陳蕃，或志寧社稷，或方直不回，前以讒勝，並伏誅戮，海內默默，人懷震憤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-37', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '陳蕃、竇武奮義草謀，徵會天下，名士有識所共聞也，而張奐見欺豎子，揚戈以斷忠烈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-065-38', 'p0421', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐被曹節等矯制，使率五營士圍殺陳蕃、竇武等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-39', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '陳蕃字仲舉，汝南平輿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-40', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '前太尉陳蕃，忠清直亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-41', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」太傅陳蕃，輔弼先帝，出內累年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-42', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '論曰：桓、靈之世，若陳蕃之徒，咸能樹立風聲，抗論惛俗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-066-43', 'p0421', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '贊曰：陳蕃蕪室，志清天綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-44', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '並與李膺、陳蕃、王暢更相襃重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-45', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '竇武、劉淑、陳蕃為「三君」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-46', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-47', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '翟超，山陽太守，事見陳蕃傳，字及郡縣未詳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-48', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '案經三府，太尉陳蕃卻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-49', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及陳蕃免太尉，朝野屬意於膺，荀爽恐其名高致禍，欲令屈節以全亂世，為書貽曰：「乆廢過庭，不聞善誘，陟岵瞻望，惟日為歲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-50', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '頃聞上帝震怒，貶黜鼎臣，上帝謂天子，鼎臣即陳蕃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-51', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃為太傅，與大將軍竇武共秉朝政，連謀誅諸宦官，故引用天下名士，乃以膺為長樂少府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-52', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '後太傅陳蕃輔政，復為太僕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-53', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '靈帝初，陳蕃輔政，以祐為河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0421-a03-067-54', 'p0421', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '尚書令陳蕃薦朗公忠亮直，宜在機密，復徵為尚書。');
